const $=s=>document.querySelector(s);
let data={};let cloudLoadId=-1;
let active='one', quiz=null, step=0;
const empty=()=>({name:'',goal:'Общение с бразильцами',minutes:'15',experience:'С нуля',onboarded:false,diagnosis:null,attempts:[],completed:false,draft:''});
const user=()=>data[active]||(data[active]=empty());
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){window.BoraAccount?.queue(user())}
function diagnosis(){return user().onboarded?window.BoraPlacement.page(user()):start()}
function result(){return window.BoraPlacement.resultPage(user())}
function home(){if(window.BoraUI)return window.BoraUI.home(user());const u=user(),nextLesson=window.BoraStudy?.next(u);return `<section class="hero"><div class="hero-copy"><div class="eyebrow">Português do Brasil · маленькими шагами</div><h1>${u.onboarded?`Oi, ${esc(u.name)}!<br>Продолжим?`:'Ближе к Бразилии.<br>С каждой фразой.'}</h1><p>Понимай, как устроен язык. Говори о том, что важно тебе. Учись в своём темпе.</p><a class="btn yellow" href="#${!u.onboarded?'start':!u.diagnosis?'diagnosis':nextLesson?'courses/pt/'+nextLesson.id:'courses/pt'}">${!u.onboarded?'Начать знакомство':!u.diagnosis?'Узнать стартовый уровень':'Продолжить занятие'} ↗</a><p class="small" style="margin-top:17px">Без спешки. Без сложных объяснений.</p></div><div class="hero-photo" role="img" aria-label="Рио-де-Жанейро на закате"><span class="photo-caption">Rio de Janeiro, Brasil ☀</span></div></section>${window.BoraStudy?.dashboard(u)||''}<div class="section-head"><h2>Твой следующий шаг</h2><span class="small">Um passo de cada vez</span></div><section class="grid"><article class="card green"><span class="number">01 / ЗНАКОМСТВО</span><h3>Начнём с тебя</h3><p>Твоя цель, опыт и удобное время занятий.</p><a href="#start">${u.onboarded?'Изменить профиль':'Рассказать о себе'} →</a></article><article class="card"><span class="number">02 / СТАРТОВАЯ ТОЧКА</span><h3>Что уже получается?</h3><p>Короткая проверка с изменением сложности. Можно отвечать «Не знаю».</p><a href="#diagnosis">${u.diagnosis?'Посмотреть и пройти снова':'Пройти диагностику'} →</a></article><article class="card city"><span class="number">03 / ПЕРВЫЙ РАЗГОВОР</span><h3>Oi! Tudo bem?</h3><p>30 уроков: первые фразы, жизнь в Бразилии и связная речь.</p><a href="#courses/pt">Открыть программу →</a></article></section><div class="notice">Задавай вопросы в разделе «Помощник»: объяснения с опорой на учебную библиотеку. Прогресс сохраняется в твоём аккаунте после входа. Бразильский португальский: 30 уроков с объяснениями на русском и личным маршрутом.</div>`}
function start(){const u=user();return `<div class="narrow panel"><div class="eyebrow">Начало обучения</div><h1>Давай познакомимся</h1><form id="onboarding"><label>Как тебя называть?<input name="name" maxlength="40" required value="${esc(u.name)}" autocomplete="given-name" placeholder="Твоё имя"></label><details class="start-preferences"><summary>Настроить цель и время занятий — необязательно</summary><label>Для чего учишь португальский?<select name="goal">${['Общение с бразильцами','Общение и подготовка к Celpe-Bras','Пока определяюсь'].map(x=>`<option ${u.goal===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Сколько минут в день удобно?<select name="minutes">${['10','15','25'].map(x=>`<option ${u.minutes===x?'selected':''}>${x}</option>`).join('')}</select></label>${u.onboarded?'<button class="btn alt" type="submit" name="startWith" value="preferences">Сохранить настройки</button>':''}</details><h2>С чего начнём?</h2><div class="start-options"><div><p>Совсем не знаешь португальский? Начни с приветствий. Проверка не нужна.</p><button class="btn yellow" name="startWith" value="basics" type="submit">Начать с первых слов →</button></div><div><p>Уже немного знаешь? Несколько заданий помогут выбрать начальную тему.</p><button class="btn alt" name="startWith" value="test" type="submit">Сначала проверить знания →</button></div></div></form></div>`}

const pages=[
{title:'Первое «привет»',body:'В Бразилии можно начать дружеский разговор с Oi! Это короткое «Привет!». Чтобы спросить «Как дела?», добавь Tudo bem?',pt:'Oi! Tudo bem?',ru:'Привет! Как дела?',why:'Буквально tudo bem — «всё хорошо». С вопросительной интонацией это вопрос, а как ответ — «всё хорошо».',q:'Что подходит для дружеского начала разговора?',options:['Oi! Tudo bem?','Até amanhã!','Obrigado!'],answer:0},
{title:'Как представиться',body:'Eu означает «я», sou — «есть / являюсь» в этой фразе. По-русски мы говорим «Я Анна», а по-португальски оставляем глагол: Eu sou a Ana.',pt:'Oi! Eu sou a Ana.',ru:'Привет! Я Анна.',why:'Артикль a перед именем встречается во многих регионах Бразилии. Форма Eu sou Ana тоже возможна. Для имени мужчины в такой конструкции используется o.',q:'Как представиться, если тебя зовут Ана?',options:['Eu estou Ana.','Eu sou a Ana.','Eu tenho Ana.'],answer:1},
{title:'Откуда ты?',body:'Чтобы сказать, откуда ты, используем sou de. Например, Eu sou de Moscou — «Я из Москвы». Для России: Eu sou da Rússia.',pt:'Eu sou da Rússia.',ru:'Я из России.',why:'Da получается из de + a. С названием Rússia обычно употребляется артикль a. Поэтому здесь da Rússia.',q:'Как сказать «Я из России»?',options:['Eu moro Rússia.','Eu estou Rússia.','Eu sou da Rússia.'],answer:2}
];
function lesson(){if(!user().onboarded)return `<div class="narrow panel"><h1>Начнём со знакомства</h1><a class="btn" href="#start">Заполнить профиль</a></div>`;const p=pages[step];return `<div class="narrow"><a class="back" href="#home">← Мой путь</a><div class="panel"><div class="eyebrow">Знакомство · шаг ${step+1} из 3</div><progress value="${step}" max="3" aria-label="Шаг занятия"></progress><h1 style="margin-top:24px">${p.title}</h1><p>${p.body}</p><div class="example"><strong lang="pt-BR">${p.pt}</strong><p>${p.ru}</p><span class="small">Аудио носителя ещё не добавлено</span></div><details><summary>Почему так устроено?</summary><p>${p.why}</p></details><h3 style="margin-top:24px">${p.q}</h3><div class="options">${p.options.map((x,i)=>`<button class="option" data-lesson-answer="${i}">${x}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite"></div><label for="draft">Твоя фраза или вопрос к объяснению</label><textarea id="draft" placeholder="Попробуй представиться по-португальски…">${esc(user().draft||'')}</textarea><p class="small">Сохраняется как заметка. Для разбора фразы открой <a href="#assistant">помощника</a>.</p><div class="row">${step?'<button class="btn alt" id="previous">← Назад</button>':''}<button class="btn" id="next" disabled>${step===2?'Завершить занятие':'Следующий шаг →'}</button></div></div></div>`}
function progress(){const u=user(),courseSummary=window.BoraLearning?.summary(u)||[],courseDone=courseSummary.reduce((n,s)=>n+s.done,0),courseRecords=Object.entries(u.courseProgress||{}).filter(([key])=>key.startsWith('pt/')).map(([,record])=>record),totalAttempts=u.attempts.length+courseRecords.reduce((n,r)=>n+(r.attempts||0)+(r.reviewAttempts||0),0),correct=u.attempts.filter(a=>a.correct).length+courseRecords.reduce((n,r)=>n+(r.correct||0)+(r.reviewCorrect||0),0);return `<div class="narrow"><div class="eyebrow">Твой прогресс</div><h1>Каждый шаг считается.</h1><section class="grid stats-grid"><div class="card"><div class="stat">${(u.completed?1:0)+courseDone}</div><p>Занятий завершено</p></div><div class="card"><div class="stat">${totalAttempts}</div><p>Попыток в упражнениях</p></div><div class="card green"><div class="stat">${correct}</div><p>Правильных ответов</p></div></section><div class="panel" style="margin-top:24px"><h2>Твои результаты по курсу</h2>${courseSummary.map(s=>`<p><a href="#courses/${s.course.id}">${esc(s.course.title)}</a> · ${s.done} из ${s.total}</p>`).join('')}${window.BoraAssess?.progress(u)||''}<h2>Что уже проверили</h2><p>${u.diagnosis?esc(u.diagnosis.summary):'Диагностика ещё не пройдена.'}</p><p>${u.completed?'Пройдено занятие «Знакомство». Чтобы закрепить навык, повтори его позже без подсказок.':'Открой программу и выбери небольшой урок.'}</p><a class="btn" href="#courses">Посмотреть все занятия</a><h3 style="margin-top:25px">Последние попытки</h3>${window.BoraStudy?.history(u)||'<p class="small">Здесь появятся результаты упражнений.</p>'}</div><div class="notice">Один завершённый урок не означает освоения языка. Говорение и произношение в этом прототипе не оценивались.</div></div>`}
function render(){window.BoraDrill?.stop();window.BoraDictionary?.stop();window.BoraKit?.stop();window.BoraLessons?.stop();window.BoraAssess?.stop();window.BoraUI?.stop();window.BoraStudy?.stop();window.BoraLivePractice?.stop();window.BoraPractice?.stop();window.BoraAudio?.stop();let route=(location.hash.slice(1)||'home').split('/')[0];if(['assistant','practice','live'].includes(route)){const id=location.hash.split('/')[1];location.hash='courses/pt/'+(window.BoraCourses[0].lessons.some(l=>l.id===id)?id:'oi');return}const account=window.BoraAccount;if(account?.ready&&account.signedIn&&!account.error&&!account.recovery&&route==='account'&&['login','register'].includes(location.hash.split('?')[0].split('/')[1])){location.hash=user().onboarded?(account.loginDestination?.()||'home'):'start';return}if(account?.ready&&account.signedIn&&!account.error&&!user().onboarded&&!['account'].includes(route))route='start';const isCourseLesson=route==='courses'&&location.hash.split('/').length>=3;if(account){if(!account.ready){$('#app').innerHTML='<div class="narrow panel"><h1>Загружаю аккаунт…</h1></div>';return}if(account.recovery||(route==='home'&&account.error)||((['start','diagnosis','lesson','progress','assistant','result','practice','live','review','test','exam','dictionary'].includes(route)||isCourseLesson)&&(!account.signedIn||account.error)))route='account';}$('#app').innerHTML=({home,start,diagnosis,lesson,progress:()=>window.BoraKit?.results(user())||progress(),unit:()=>window.BoraKit.preview(user()),dictionary:()=>window.BoraKit.dictionary(user()),test:()=>window.BoraAssess.page(user()),exam:()=>window.BoraAssess.page(user()),account:()=>window.BoraAccount.page(),courses:()=>window.BoraLessons?window.BoraLessons.page(user()):window.BoraLearning.page(user()),assistant:()=>window.BoraAssistant.page(user()),review:()=>window.BoraStudy.reviewPage(user()),practice:()=>window.BoraPractice.page(user()),live:()=>window.BoraLivePractice.page(user()),result:()=>user().diagnosis?result():diagnosis()}[route]||home)();if($('#account-link')){$('#account-link').textContent=window.BoraAccount?.signedIn?(user().name||'Мой аккаунт'):'Войти';$('#account-link').href=window.BoraAccount?.signedIn?'#account':'#account/login';}if($('#cloud-status'))$('#cloud-status').textContent=/не сохранено|ошиб|интернет|другом устройстве/i.test(window.BoraAccount?.status||'')?'Не удалось сохранить. Открой аккаунт.':'';window.BoraProfile?.sync(window.BoraAccount,render);window.BoraProfile?.paint(user().name);window.BoraUI?.refresh(route);bind();window.BoraUI?.bind(user(),save,render);window.BoraKit?.bind(user(),save,render);window.BoraDictionary?.bind(user(),save,render);window.BoraPlacement?.bind(user(),save,render);window.BoraAssistant?.bind(user(),save);window.BoraPractice?.bind(user(),save);window.BoraLivePractice?.bind(user(),save);window.BoraLearning?.bind(user(),save,render);window.BoraLessons?.bind(user(),save,render);window.BoraStudy?.bindReview(user(),save,render);window.BoraAssess?.bind(user(),save,render);window.BoraComfort?.bind(user(),save,render);window.BoraAudio?.bind();window.BoraProfile?.bind();window.BoraAccount?.bind(user,state=>{data.one=Object.assign(empty(),state);render()})}
function bind(){const f=$('#onboarding');if(f)f.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));if(!v.name.trim())return;Object.assign(user(),v,{name:v.name.trim(),onboarded:true,program:'pt'});if(e.submitter?.value==='preferences'){save();location.hash='home'}else if(e.submitter?.value==='test'){if(user().experience==='С нуля')user().experience='Знаю отдельные слова';save();location.hash='diagnosis'}else{window.BoraPlacement.chooseBasics(user());save();location.hash='courses/pt/oi'}};document.querySelectorAll('[data-lesson-answer]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.lessonAnswer)===pages[step].answer;user().attempts.push({step,correct,at:new Date().toISOString()});save();$('#feedback').className='feedback'+(correct?'':' bad');$('#feedback').textContent=correct?'Верно! '+pages[step].why:'Пока не совсем. '+pages[step].why+' Попробуй ещё раз.';if(correct){document.querySelectorAll('[data-lesson-answer]').forEach(x=>x.disabled=true);$('#next').disabled=false}});if($('#draft'))$('#draft').oninput=e=>{user().draft=e.target.value;save()};if($('#previous'))$('#previous').onclick=()=>{step--;render()};if($('#next'))$('#next').onclick=()=>{if(step<2){step++;render();window.scrollTo(0,0)}else{user().completed=true;save();step=0;location.hash='progress'}}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();window.BoraAccount?.init(()=>{const a=window.BoraAccount;if(a.ready&&a.loadId!==cloudLoadId){cloudLoadId=a.loadId;data={one:Object.assign(empty(),a.state||{})};quiz=null;step=0}render()});
